+		if (rtl && ellipsis_pos >= 0) {
+			for (int gl_idx = ellipsis_gl_size - 1; gl_idx >= 0; gl_idx--) {
+				for (int j = 0; j < ellipsis_glyphs[gl_idx].repeat; j++) {
