+					}
+					processed_glyphs_step++;
+					offset_step.x += ellipsis_glyphs[gl_idx].advance;
+				}
+			}
+		} /* Draw main text. */
+		for (int j = 0; j < gl_size; j++) { /* Trim when necessary. */
+			if (trim_pos >= 0) {
